import {scenes,steps,buildRecord} from './data.js';
const $=s=>document.querySelector(s),main=$('#main'),key='respeak.practice.v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let records=[],storageOK=true,session=null,route='home',timer=null;
try { const saved=JSON.parse(localStorage.getItem(key)||'[]'); if(Array.isArray(saved)) records=saved.filter(r=>r&&typeof r.id==='string'&&scenes.some(s=>s.id===r.sceneId)&&typeof r.rewrite==='string'); } catch {storageOK=false;}
function persist(){try{localStorage.setItem(key,JSON.stringify(records));return true;}catch{storageOK=false;toast('浏览器未允许保存。请导出记录，关闭页面后可能丢失。');return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function updateNav(){ $('#record-count').textContent=records.length;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===route)); }
function show(html){main.innerHTML=html;updateNav();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
function illustration(s,interactive=false){return `<div class="art ${interactive?'interactive':''}" style="--scene:${s.color}"><img src="./assets/${s.id}.svg" alt="${s.place}的原创插画" ${interactive?'':'loading="lazy"'}>${interactive?s.objects.map((o,i)=>`<button class="hotspot" style="left:${o.x}%;top:${o.y}%" data-object="${i}" aria-label="查看${o.name}"><span>＋</span><em>${o.name}</em></button>`).join(''):''}</div>`;}
function home(){delete main.dataset.scene;delete main.dataset.step;route='home';show(`<section class="hero"><div class="hero-copy"><span class="eyebrow"><i></i> 给日常关系，一次温柔的练习</span><h1>有些话，<br>可以<span class="handline">重新说。</span><svg class="spark" viewBox="0 0 50 60" aria-hidden="true"><path d="M8 32l15-8M28 14l4-12M34 35l14 2"/></svg></h1><p>那些脱口而出的锋利，背后也许只是没被听见的在意。<br class="desktop">在这里，停一下，听听自己，再试着说一次。</p><button class="primary" data-start="dorm">开始一次练习 <span>↗</span></button><span class="hero-note">约 3–5 分钟 · 不必说得完美</span></div><div class="hero-visual">${illustration(scenes[0])}<span class="sticker">“其实，我想说的是……”</span><div class="floating-note"><span>✳</span> 先照顾情绪，再整理语言。</div></div></section><section class="intro-strip" aria-label="作品特点"><span><b>01</b> 走进熟悉的日常</span><span><b>02</b> 留一小段私人暂停</span><span><b>03</b> 练习更清楚地表达</span><small>预设剧情体验 · 无需登录</small></section><section class="stories"><div class="section-head"><div><span class="eyebrow">STORIES TO STEP INTO</span><h2>从哪一句，重新开始？</h2></div><p>五段生活切片，没有标准答案。<br>选一个此刻让你有共鸣的场景。</p></div><div class="scene-grid">${scenes.map((s,i)=>`<button class="scene-card" data-start="${s.id}" aria-label="进入${s.tag}：${s.title}"><div class="card-art">${illustration(s)}<span class="scene-no">0${i+1}</span><span class="card-time">${s.time}</span></div><div class="card-copy"><span class="tag">${s.tag}</span><h3>${s.title}<span>↗</span></h3><p>${s.subtitle}</p><div class="card-bottom"><span>${records.some(r=>r.sceneId===s.id)?'✓ 已留下练习':'约 3–5 分钟'}</span><span>进入故事 →</span></div></div></button>`).join('')}<aside class="quote-card"><span class="quote-mark">“</span><h3>好好说话，<br>不是把情绪藏起来。</h3><p>是让真正重要的东西，<br>被听见。</p><div class="leaf">✳</div><small>每一次重说，都是一次靠近。</small></aside></div></section><section class="privacy-note"><span>⌁</span><p><b>这是一间安全的练习室。</b>所有人物、回应与结局均为预设剧情，不会根据输入生成。记录仅保存在当前浏览器，不上传服务器。你可以随时离开，也可以重新开始。</p><button data-nav="about">了解作品 →</button></section>${!storageOK?'<p class="warning">本地存储不可用，本次记录可能无法持久保存。完成后可导出备份。</p>':''}`);}
function begin(id){const scene=scenes.find(s=>s.id===id);if(!scene)return;session={scene,step:0,goal:'',need:'',regulation:'',dialog:[],round:0,rewrite:'',feeling:'',saved:false};route='practice';practice();}
function practice(){const s=session.scene,st=session.step;const keepScroll=main.dataset.scene===s.id&&Number(main.dataset.step)===st, scrollY=window.scrollY;route='practice';show(`<section class="practice-heading"><button class="text-btn" data-exit>← 返回故事小屋</button><span class="tag">${s.tag} · 预设剧情</span></section><ol class="stepper" aria-label="练习进度">${steps.map((v,i)=>`<li class="${i===st?'current':i<st?'done':''}" ${i===st?'aria-current="step"':''}><span>${i<st?'✓':i+1}</span><b>${v}</b></li>`).join('')}</ol><div class="practice-layout"><aside class="scene-panel">${illustration(s,true)}<div class="scene-caption"><span>${s.time} / ${s.place}</span><h2>${s.title}</h2><p>${s.subtitle}</p></div><div class="object-tip" id="object-tip" aria-live="polite">✧ 点击画面里的物件，发现一句小提示。</div><p class="preset-note">固定人物与预设回应 · 自由输入不触发生成</p></aside><section class="exercise" aria-label="${steps[st]}">${stageContent()}</section></div>`); if(st===4)bindEditor();main.dataset.scene=s.id;main.dataset.step=st;if(keepScroll)window.scrollTo(0,scrollY);else if(st>0&&matchMedia('(max-width:640px)').matches)$('.exercise').scrollIntoView({block:'start'});}
function stageContent(){const s=session.scene,st=session.step;const heading=(n,t,p)=>`<span class="eyebrow">${n} / A MOMENT TO REPHRASE</span><h2>${t}</h2><p class="lead">${p}</p>`;
if(st===0)return heading('01','故事从这里开始','先看见发生了什么，不急着解决。')+`<p class="story-text">${s.intro}</p><div class="bubble"><small>${s.person} · ${s.role}</small><p>“${s.trigger}”</p></div><div class="original"><span>那句差点脱口而出的话</span><p>“${s.original}”</p></div><button class="primary wide" data-next>走进这一刻 →</button>`;
if(st===1)return heading('02','这一次，你想靠近什么？','选择一个练习目标。你不需要在一次对话里解决所有事。')+`<div class="options">${s.goals.map((g,i)=>`<button class="option ${session.goal===g?'selected':''}" data-goal="${i}" aria-pressed="${session.goal===g}"><span>0${i+1}</span>${g}<b>↗</b></button>`).join('')}</div><p class="small-note">目标是表达自己的需要，而不是控制对方的反应。</p><button class="primary wide" data-next ${session.goal?'':'disabled'}>带着这个目标，开始交流 →</button>`;
if(st===2){return heading('03','先试着聊两句','看看一种熟悉的表达，可能让对话走向哪里。')+`<div class="chat" aria-live="polite"><div class="chat-line other"><small>${s.person}</small><p>${s.trigger}</p></div>${session.dialog.map(d=>`<div class="chat-line ${d.who}"><small>${d.who==='me'?'你':s.person}</small><p>${esc(d.text)}</p></div>`).join('')}</div>${session.round===0?`<p class="choice-label">你想如何回应？</p><div class="dialog-options">${s.choices.map((c,i)=>`<button class="option" data-say="${i}">${c[0]}<b>→</b></button>`).join('')}</div>`:session.round===1?`<div class="dialog-options"><button class="option" data-round="direct">我想把我的需要说清楚。<b>→</b></button><button class="option" data-round="pause">我有点乱，想先停一会儿。<b>→</b></button></div>`:`<div class="hint">对话不必马上继续。先回到自己这里。</div><button class="primary wide" data-next>给自己一个私人暂停 →</button>`}`;}
if(st===3)return heading('04','先听听，自己的声音。','这里是私人暂停区。这里的选择不会发送给故事中的人物。')+`<div class="breath"><div class="breath-orbit"><span>慢慢吸气<br><small>再缓缓呼气</small></span></div><p>不赶时间，按你舒服的节奏。</p></div><fieldset><legend>此刻，我更需要……</legend><div class="chips">${s.needs.map((n,i)=>`<button class="chip ${session.need===n?'selected':''}" data-need="${i}" aria-pressed="${session.need===n}">${n}</button>`).join('')}</div></fieldset><fieldset><legend>给自己一句提醒</legend><div class="chips">${['我可以表达不舒服','我可以清楚地说不','我不必马上解决一切'].map((n,i)=>`<button class="chip ${session.regulation===n?'selected':''}" data-regulate="${i}" aria-pressed="${session.regulation===n}">${n}</button>`).join('')}</div></fieldset><button class="primary wide" data-next ${session.need&&session.regulation?'':'disabled'}>准备好了，重说一句 →</button>`;
if(st===4)return heading('05','如果再给你一次机会……','不用讨好，也不用完美。把真正想表达的事情，换一种说法。')+`<div class="rewrite-context"><span>我的目标：${session.goal}</span><span>我的需要：${session.need}</span></div><label class="editor-label" for="rewrite">这一次，我想说</label><textarea id="rewrite" maxlength="500" placeholder="当……的时候，我感到……，因为我需要……，你愿意……吗？">${esc(session.rewrite)}</textarea><div class="editor-foot"><button class="text-btn" data-example>试试参考表达 ↗</button><span id="char-count">${session.rewrite.length}/500</span></div><div class="writing-hints"><span>① 具体发生的事</span><span>② 自己的感受和需要</span><span>③ 可以协商的请求</span></div><p class="small-note">参考句只是脚手架。你也可以直接表达边界；不必遵循固定句式。</p><button class="primary wide" id="rewrite-next" data-next ${session.rewrite.trim().length>=2?'':'disabled'}>看看两次表达的不同 →</button>`;
if(st===5)return heading('06','同一份在意，不同的表达。','重说不是否定当时的自己，而是多拥有一种选择。')+`<div class="comparison before"><span>原版 · 情绪先开了口</span><blockquote>${s.original}</blockquote></div><div class="compare-arrow">↓ 给真正的需要一点空间</div><div class="comparison after"><span>新版 · 你的重新表达</span><blockquote>${esc(session.rewrite)}</blockquote></div><div class="ending"><span>预设剧情 · 一种可能的回应</span><p>${s.ending}</p><small>这段结局是固定示例，未分析你的输入，也不保证现实中的对方会这样回应。</small></div><button class="primary wide" data-next>收好这次练习 →</button>`;
return heading('07','把这一点改变，带回生活。','你已经给了那句话一次重新出发的机会。')+`<div class="review-card"><span class="review-symbol">✳</span><div><small>这次，你练习了</small><h3>${session.goal}</h3><p>从情绪出发，看见「${session.need}」。</p></div></div><fieldset><legend>此刻的感觉，更接近哪一种？</legend><div class="chips">${['松了一口气','更清楚了一点','还需要一点时间'].map((f,i)=>`<button class="chip ${session.feeling===f?'selected':''}" data-feeling="${i}" aria-pressed="${session.feeling===f}">${f}</button>`).join('')}</div></fieldset><div class="boundary"><b>带走一句提醒</b><p>${s.boundary}</p></div>${session.saved?`<div class="saved-message" role="status">${storageOK?'✓ 这次练习已保存到当前浏览器':'本次记录已暂存，建议导出备份。'}</div><button class="primary wide" data-nav="records">查看我的练习 →</button><button class="text-btn wide" data-nav="home">再走进一个故事</button>`:`<button class="primary wide" data-save ${session.feeling?'':'disabled'}>保存这次练习 ✓</button><p class="small-note">仅保存在此浏览器；清除浏览器数据会移除记录。</p>`}`;
}
function bindEditor(){const el=$('#rewrite');el.addEventListener('input',()=>{session.rewrite=el.value;$('#char-count').textContent=`${el.value.length}/500`;$('#rewrite-next').disabled=el.value.trim().length<2;});}
function recordsView(){route='records';show(`<section class="records-head"><span class="eyebrow">WORDS WORTH KEEPING</span><h1>我的练习手记<span> ${records.length.toString().padStart(2,'0')}</span></h1><p>把重新说过的话，留给下一次需要勇气的自己。</p><div class="record-tools"><button class="secondary" data-export ${records.length?'':'disabled'}>导出记录 ↓</button><span>仅保存在此浏览器 · 不上传</span></div></section>${!storageOK?'<p class="warning">浏览器存储不可用。请及时导出记录，当前页面关闭后可能丢失。</p>':''}${records.length?`<div class="records-list">${[...records].reverse().map(r=>`<article class="record"><div class="record-meta"><span class="tag">${scenes.find(s=>s.id===r.sceneId).tag}</span><time>${esc(new Date(r.createdAt).toLocaleString('zh-CN'))}</time></div><h2>${esc(r.title)}</h2><p class="record-goal">${esc(r.goal)} · ${esc(r.feeling)}</p><div class="record-pair"><div><small>原来的话</small><p>${esc(r.original)}</p></div><div><small>重说的一句</small><p>${esc(r.rewrite)}</p></div></div><div class="record-actions"><button class="text-btn" data-start="${r.sceneId}">再练一次 ↗</button><button class="text-btn danger" data-delete="${esc(r.id)}">删除记录</button></div></article>`).join('')}</div>`:`<div class="empty"><span>✎</span><h2>这里，等着你的第一句重说。</h2><p>走进一个故事，给自己几分钟。<br>完成后，你的表达会被好好收在这里。</p><button class="primary" data-nav="home">去选一个故事 →</button></div>`}`);}
function about(){ $('#info-content').innerHTML=`<span class="eyebrow">ABOUT THIS LITTLE ROOM</span><h2>这句话，我想重说</h2><p>一个以日常沟通为主题的互动叙事作品。五个原创场景，邀请你从冲突中停一下，辨认需要，再练习更清楚的表达。</p><h3>预设剧情，不是 AI 对话</h3><p>人物、选项、回应、插画与结局均为预先编写。自由输入只展示在对比和记录中，不会被模型分析，不会改变结局。没有模型、密钥或后端依赖。</p><h3>你的记录，由你保管</h3><p>练习完成后手动保存到当前设备浏览器的 localStorage，可逐条删除或导出 JSON。无登录、无分析追踪、无数据上传。隐私浏览或清理站点数据可能使记录丢失。请避免填写可识别个人身份的信息。</p><h3>练习的边界</h3><p>本作品是表达练习，不提供心理诊断或专业咨询，不要求你以沟通解决所有冲突。面对威胁、暴力或持续伤害，请优先保障安全，寻求可信任的人或专业支持。</p><p class="small-note">原创矢量插画 · 独立静态部署 · 参赛展示版 v1.0</p>`;$('#info').showModal();}
function exitConfirm(dest){if(session&&!session.saved&&route==='practice'){ $('#info-content').innerHTML='<h2>先离开一会儿？</h2><p>本次尚未保存的内容会被丢弃。已保存的练习记录会保留。</p><button class="secondary" id="confirm-exit">离开这次练习</button>';$('#info').showModal();$('#confirm-exit').onclick=()=>{$('#info').close();session=null;dest==='records'?recordsView():home();};}else{session=null;dest==='records'?recordsView():home();}}
document.addEventListener('click',event=>{const b=event.target.closest('button,a.brand');if(!b||b.disabled)return;
if(b.matches('a.brand')){event.preventDefault();exitConfirm('home');return;}
if(b.dataset.nav){if(b.dataset.nav==='about')about();else exitConfirm(b.dataset.nav);return;}
if(b.hasAttribute('data-start')){begin(b.dataset.start);return;}
if(b.hasAttribute('data-exit')){exitConfirm('home');return;}
if(b.hasAttribute('data-export')){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='这句话我想重说-练习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('记录已导出，请妥善保管。');return;}
if(b.hasAttribute('data-delete')){const id=b.dataset.delete;$('#info-content').innerHTML='<h2>删除这次练习？</h2><p>删除后无法恢复；你可以先导出一份备份。</p><button class="secondary danger" id="confirm-delete">确认删除</button>';$('#info').showModal();$('#confirm-delete').onclick=()=>{records=records.filter(r=>r.id!==id);persist();$('#info').close();recordsView();toast('已删除这次练习。');};return;}
if(!session)return;
if(b.hasAttribute('data-object')){const o=session.scene.objects[Number(b.dataset.object)];$('#object-tip').textContent=`${o.name} · ${o.text}`;return;}
if(b.hasAttribute('data-goal')){session.goal=session.scene.goals[Number(b.dataset.goal)];practice();}
if(b.hasAttribute('data-say')){const c=session.scene.choices[Number(b.dataset.say)];session.dialog.push({who:'me',text:c[0]},{who:'other',text:c[1]},{who:'other',text:session.scene.follow});session.round=1;practice();}
if(b.hasAttribute('data-round')){session.dialog.push({who:'me',text:b.dataset.round==='direct'?'我想把我的需要说清楚。':'我有点乱，想先停一会儿。'},{who:'other',text:'好，我们都先缓一缓，等会儿再聊。'});session.round=2;practice();}
if(b.hasAttribute('data-need')){session.need=session.scene.needs[Number(b.dataset.need)];practice();}
if(b.hasAttribute('data-regulate')){session.regulation=['我可以表达不舒服','我可以清楚地说不','我不必马上解决一切'][Number(b.dataset.regulate)];practice();}
if(b.hasAttribute('data-example')){if(session.rewrite.trim()){ $('#info-content').innerHTML='<h2>替换当前表达？</h2><p>使用参考表达会替换你已输入的内容。你也可以关闭此窗口继续自己的表达。</p><button class="secondary" id="use-example">使用参考表达</button>';$('#info').showModal();$('#use-example').onclick=()=>{$('#info').close();session.rewrite=session.scene.suggestion;practice();};}else{session.rewrite=session.scene.suggestion;practice();} }
if(b.hasAttribute('data-feeling')){session.feeling=['松了一口气','更清楚了一点','还需要一点时间'][Number(b.dataset.feeling)];practice();}
if(b.hasAttribute('data-save')&&!session.saved){records.push(buildRecord(session.scene,session));session.saved=true;persist();practice();}
if(b.hasAttribute('data-next')){if(session.step===4)session.rewrite=session.rewrite.trim();session.step=Math.min(session.step+1,6);practice();}
});
$('#close-info').onclick=()=>$('#info').close();
window.addEventListener('beforeunload',e=>{if(session&&!session.saved){e.preventDefault();e.returnValue='';}});
home();
